// Leexi on the company's own API key: every operation of Leexi's public API (calls with their transcripts and AI
// notes, call notes, meeting events and the meeting assistant, users, teams, and a reseller's client companies).
// actions.json is generated by `bun scripts/openapi-actions.ts leexi`; upload_recording is written here on top.
// Leexi's webhooks can't be registered through the API, so new calls and meetings are polled (polls/leexi.ts).
import { z } from "zod";
import { AppFile, AppsError } from "../../types";
import type { OwnAction, OwnApp } from "../index";
import { type Api, call, type Send, specActions } from "../openapi";

export const api: Api = {
  name: "Leexi",
  base: "https://public-api.leexi.ai/v1",
  tokenHelp: "Leexi → Settings → Advanced → API Keys",
  // HTTP Basic with the key ID as the login and the secret as the password
  auth: (key) => ({ Authorization: `Basic ${Buffer.from(key).toString("base64")}` }),
  failed: (body) => (body?.success === false ? String(body.message ?? "the request failed") : undefined),
};

const CALLS = { method: "GET", path: "/calls", query: ["items"], headers: [] };

// Leexi's two steps for a recording (an address to upload to, then the upload itself) as one
const upload_recording: OwnAction = {
  description:
    "Upload a call recording (audio or video) to Leexi, ready to become a call. Answers recording_s3_key: pass it to create_call within 3 days, or the upload expires.",
  readOnly: false,
  input: z.object({
    file: z.any().describe('The recording, a file from the computer: {"file": "/work/meeting.mp3"}. Audio (.mp3 .wav .m4a .ogg ...) or video (.mp4 .mov .webm ...)'),
  }),
  run: async (i, key) => {
    const file = i.file;
    if (!(file instanceof AppFile)) throw new AppsError('file: give the recording as {"file": "/work/..."}');
    const extension = /\.[a-z0-9]+$/i.exec(file.name)?.[0]?.toLowerCase();
    if (!extension) throw new AppsError("file: the recording's name needs its extension, like call.mp3");
    const out = (await call(api, key, { method: "POST", path: "/calls/presign_recording_url", query: [], headers: [], body: { kind: "fields", fields: [["extension", "extension"]] } }, { extension })) as {
      data: { url: string; recording_s3_key: string; headers?: Record<string, string> };
    };
    const put = await fetch(out.data.url, { method: "PUT", headers: out.data.headers ?? {}, body: file.bytes as Uint8Array<ArrayBuffer> });
    if (!put.ok) throw new AppsError(`Leexi: the upload failed (${put.status})`);
    return { recording_s3_key: out.data.recording_s3_key };
  },
};

// Leexi (Rails) reads a list in the query as name[]=a&name[]=b, which the spec leaves to its descriptions: those
// params are sent under that name
const SPEC = new URL("./actions.json", import.meta.url);
async function actions() {
  const out = await specActions(SPEC, api);
  const { actions } = (await Bun.file(SPEC).json()) as { actions: { name: string; input: { properties: Record<string, { type?: string }> }; send: Send }[] };
  for (const a of actions) {
    const lists = a.send.query.filter((k) => a.input.properties[k]?.type === "array");
    if (!lists.length) continue;
    const send = { ...a.send, query: a.send.query.map((k) => (lists.includes(k) ? `${k}[]` : k)) };
    out[a.name]!.run = (i: Record<string, unknown>, key: string) => call(api, key, send, { ...i, ...Object.fromEntries(lists.map((k) => [`${k}[]`, i[k]])) });
  }
  return out;
}

export const leexi: OwnApp = {
  app: "leexi",
  name: "Leexi",
  logo: "/logos/leexi.svg",
  keyField: {
    label: "API key ID and secret",
    help: 'In Leexi, open Settings → Advanced → API Keys and click Add (you need the permission to manage API keys; the public API comes with the AI Meeting plan or higher). Tick the scopes Emplio may use: Read calls at least, plus Write calls, Read/Write meeting events, Read/Write users, Read/Write teams for the rest. For Access rules, "Access to everything" lets Emplio see every call; "Linked to a user" only that person\'s. Copy the key ID and the secret (shown only once) and paste them joined by a colon: KEY_ID:SECRET',
    placeholder: "key-id:secret",
  },
  // one call, read with the default "Read calls" scope; a wrong key gets a 401
  async check(key) {
    if (!/^[^:\s]+:\S+$/.test(key)) throw new AppsError("paste the key ID and the secret joined by a colon, like KEY_ID:SECRET");
    await call(api, key, CALLS, { items: 1 });
    return "Leexi";
  },
  actions: { ...(await actions()), upload_recording },
};
